{
  "implementation": "def solve(case):
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    last = attempts[-1]
    if last['success']:
        decision = "final_accept"
        memory_append = None
        next_attempt = len(attempts)
    else:
        if len(attempts) < max_attempts:
            decision = "retry"
            memory_append = {
                "reflection": last['reflection'],
                "signature": last['failure_signature']
            }
            next_attempt = len(attempts)
        else:
            decision = "final_reject"
            memory_append = None
            next_attempt = len(attempts)
    return {
        "decision": decision,
        "memory_append": memory_append,
        "next_attempt": next_attempt
    }"
}
